module sd_data_master (
    input         clk,
    input         rst,
    input  [31:0] dat_in_tx,
    input         ack_i_s_tx,
    input  [2:0]  free_tx_bd,
    input  [31:0] dat_in_rx,
    input         ack_i_s_rx,
    input  [2:0]  free_rx_bd,
    input         cmd_busy,
    input         we_ack,
    input         cmd_tsf_err,
    input  [4:0]  card_status,
    input         tx_empt,
    input         tx_full,
    input         rx_full,
    input         busy_n,
    input         transm_complete,
    input         crc_ok,
    input         Dat_Int_Status_rst,
    input  [1:0]  transfer_type,

    output reg         re_s_tx,
    output reg         a_cmp_tx,
    output reg         re_s_rx,
    output reg         a_cmp_rx,
    output reg         we_req,
    output reg         d_write,
    output reg         d_read,
    output reg [31:0]  cmd_arg,
    output reg [15:0]  cmd_set,
    output reg         start_tx_fifo,
    output reg         start_rx_fifo,
    output reg [31:0]  sys_adr,
    output reg         ack_transfer,
    output reg [7:0]   Dat_Int_Status,
    output reg         CIDAT
);

    // Parameters (authoritative values from global defines)
    localparam CMD24  = 16'h181A;
    localparam CMD17  = 16'h111A;
    localparam CMD12  = 16'h0C1A;
    localparam ACMD13 = 16'h0D1A;
    localparam ACMD51 = 16'h331A;

    localparam SIZE           = 9;
    localparam IDLE           = 9'b000000001;
    localparam GET_TX_BD      = 9'b000000010;
    localparam GET_RX_BD      = 9'b000000100;
    localparam SEND_CMD       = 9'b000001000;
    localparam RECIVE_CMD     = 9'b000010000;
    localparam DATA_TRANSFER  = 9'b000100000;
    localparam STOP           = 9'b001000000;
    localparam STOP_SEND      = 9'b010000000;
    localparam RESEND_MAX_CNT = 3;
    localparam BD_SIZE        = 8;
    localparam BD_EMPTY       = 2;        // BD_SIZE/4 (16-bit memory)
    localparam READ_CYCLE     = 4;
    // Internal registers
    reg          send_done;
    reg          rec_done;
    reg          rec_failed;
    reg          tx_cycle;
    reg          rx_cycle;
    reg [2:0]    resend_try_cnt;
    reg [8:0]    state;
    reg [8:0]    next_state;
    reg          trans_done;
    reg          trans_failed;
    reg          internal_transm_complete;
    reg          transm_complete_q;
    reg [2:0]    bd_cnt;                 // 3 bits for READ_CYCLE=4

    // Combinational next-state logic (explicit sensitivity list)
    always @(state or free_tx_bd or free_rx_bd or tx_full or send_done or
             rec_done or rec_failed or trans_done or trans_failed or bd_cnt) begin
        next_state = state;   // default hold
        case (state)
            IDLE: begin
                if (free_tx_bd != BD_EMPTY)
                    next_state = GET_TX_BD;
                else if (free_rx_bd != BD_EMPTY)
                    next_state = GET_RX_BD;
                else
                    next_state = IDLE;
            end
            GET_TX_BD: begin
                if ((bd_cnt > (READ_CYCLE - 1)) && (tx_full == 1'b1))
                    next_state = SEND_CMD;
                else
                    next_state = GET_TX_BD;
            end
            GET_RX_BD: begin
                if (bd_cnt > (READ_CYCLE - 1))
                    next_state = SEND_CMD;
                else
                    next_state = GET_RX_BD;
            end
            SEND_CMD: begin
                if (send_done == 1'b1)
                    next_state = RECIVE_CMD;
                else
                    next_state = SEND_CMD;
            end
            RECIVE_CMD: begin
                if (rec_done == 1'b1)
                    next_state = DATA_TRANSFER;
                else if (rec_failed == 1'b1)
                    next_state = SEND_CMD;
                else
                    next_state = RECIVE_CMD;
            end
            DATA_TRANSFER: begin
                if (trans_done == 1'b1)
                    next_state = IDLE;
                else if (trans_failed == 1'b1)
                    next_state = STOP;
                else
                    next_state = DATA_TRANSFER;
            end
            STOP: begin
                next_state = STOP_SEND;
            end
            STOP_SEND: begin
                if (send_done == 1'b1)
                    next_state = IDLE;
                else
                    next_state = STOP_SEND;
            end
            default: next_state = IDLE;
        endcase
    end

    // Sequential state register and output register update
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            send_done <= 1'b0;
            rec_done <= 1'b0;
            rec_failed <= 1'b0;
            tx_cycle <= 1'b0;
            rx_cycle <= 1'b0;
            resend_try_cnt <= 3'b000;
            trans_done <= 1'b0;
            trans_failed <= 1'b0;
            internal_transm_complete <= 1'b0;
            transm_complete_q <= 1'b0;
            sys_adr <= 32'b0;
            cmd_arg <= 32'b0;
            cmd_set <= 16'b0;
            CIDAT <= 1'b0;
            Dat_Int_Status <= 8'b0;
            bd_cnt <= 3'b0;
            re_s_tx <= 1'b0;
            a_cmp_tx <= 1'b0;
            re_s_rx <= 1'b0;
            a_cmp_rx <= 1'b0;
            we_req <= 1'b0;
            d_write <= 1'b0;
            d_read <= 1'b0;
            start_tx_fifo <= 1'b0;
            start_rx_fifo <= 1'b0;
            ack_transfer <= 1'b0;
        end else begin
            state <= next_state;
            transm_complete_q <= transm_complete;
            internal_transm_complete <= transm_complete & ~transm_complete_q;

            // Default output values
            re_s_tx <= 1'b0;
            a_cmp_tx <= 1'b0;
            re_s_rx <= 1'b0;
            a_cmp_rx <= 1'b0;
            we_req <= 1'b0;
            d_write <= 1'b0;
            d_read <= 1'b0;
            start_tx_fifo <= 1'b0;
            start_rx_fifo <= 1'b0;
            ack_transfer <= 1'b0;
            CIDAT <= 1'b0;

            case (state)
                IDLE: begin
                    send_done <= 1'b0;
                    rec_done <= 1'b0;
                    rec_failed <= 1'b0;
                    tx_cycle <= 1'b0;
                    rx_cycle <= 1'b0;
                    resend_try_cnt <= 3'b000;
                    trans_done <= 1'b0;
                    trans_failed <= 1'b0;
                    internal_transm_complete <= 1'b0;
                    sys_adr <= 32'b0;
                    cmd_arg <= 32'b0;
                    cmd_set <= 16'b0;
                    CIDAT <= 1'b0;
                    bd_cnt <= 3'b0;
                end

                GET_TX_BD: begin
                    re_s_tx <= 1'b1;
                    tx_cycle <= 1'b1;
                    rx_cycle <= 1'b0;
                    cmd_set <= CMD24;
                    send_done <= 1'b0;
                    rec_done <= 1'b0;
                    rec_failed <= 1'b0;
                    trans_done <= 1'b0;
                    trans_failed <= 1'b0;
                    if (ack_i_s_tx) begin
                        if (bd_cnt == 3'd0) begin
                            sys_adr[15:0] <= dat_in_tx[15:0];
                            bd_cnt <= 3'd1;
                        end else if (bd_cnt == 3'd1) begin
                            sys_adr[31:16] <= dat_in_tx[15:0];
                            bd_cnt <= 3'd2;
                        end else if (bd_cnt == 3'd2) begin
                            cmd_arg[15:0] <= dat_in_tx[15:0];
                            bd_cnt <= 3'd3;
                        end else if (bd_cnt == 3'd3) begin
                            cmd_arg[31:16] <= dat_in_tx[15:0];
                            start_tx_fifo <= 1'b1;
                            bd_cnt <= 3'd4;
                        end
                    end
                end

                GET_RX_BD: begin
                    re_s_rx <= 1'b1;
                    tx_cycle <= 1'b0;
                    rx_cycle <= 1'b1;
                    send_done <= 1'b0;
                    rec_done <= 1'b0;
                    rec_failed <= 1'b0;
                    trans_done <= 1'b0;
                    trans_failed <= 1'b0;
                    if (transfer_type == 2'b00)
                        cmd_set <= CMD17;
                    else if (transfer_type == 2'b01)
                        cmd_set <= ACMD13;
                    else
                        cmd_set <= ACMD51;
                    if (ack_i_s_rx) begin
                        if (bd_cnt == 3'd0) begin
                            sys_adr[15:0] <= dat_in_rx[15:0];
                            bd_cnt <= 3'd1;
                        end else if (bd_cnt == 3'd1) begin
                            sys_adr[31:16] <= dat_in_rx[15:0];
                            bd_cnt <= 3'd2;
                        end else if (bd_cnt == 3'd2) begin
                            cmd_arg[15:0] <= dat_in_rx[15:0];
                            bd_cnt <= 3'd3;
                        end else if (bd_cnt == 3'd3) begin
                            cmd_arg[31:16] <= dat_in_rx[15:0];
                            bd_cnt <= 3'd4;
                        end
                    end
                end

                SEND_CMD: begin
                    bd_cnt <= 3'b0;
                    send_done <= 1'b0;
                    rec_done <= 1'b0;
                    rec_failed <= 1'b0;
                    if (rx_cycle) begin
                        d_read <= 1'b1;
                        d_write <= 1'b0;
                    end else if (tx_cycle) begin
                        d_read <= 1'b0;
                        d_write <= 1'b1;
                    end else begin
                        d_read <= 1'b0;
                        d_write <= 1'b0;
                    end
                    if (!cmd_busy) begin
                        we_req <= 1'b1;
                        if (we_ack)
                            send_done <= 1'b1;
                    end
                end

                RECIVE_CMD: begin
                    send_done <= 1'b0;
                    if (rx_cycle)
                        start_rx_fifo <= 1'b1;
                    if (!cmd_busy) begin
                        if (cmd_tsf_err) begin
                            rec_failed <= 1'b1;
                            rec_done <= 1'b0;
                            Dat_Int_Status[0] <= 1'b1;
                        end else if ((card_status[0] == 1'b1) &&
                                     ((card_status[4:1] == 4'd4) ||
                                      (card_status[4:1] == 4'd5) ||
                                      (card_status[4:1] == 4'd6))) begin
                            rec_done <= 1'b1;
                            rec_failed <= 1'b0;
                        end else begin
                            rec_done <= 1'b0;
                            rec_failed <= 1'b1;
                        end
                    end
                end

                DATA_TRANSFER: begin
                    rec_done <= 1'b0;
                    rec_failed <= 1'b0;
                    if (tx_cycle && tx_empt) begin
                        trans_failed <= 1'b1;
                        Dat_Int_Status[2] <= 1'b1;
                    end else if (rx_cycle && rx_full) begin
                        trans_failed <= 1'b1;
                        Dat_Int_Status[2] <= 1'b1;
                    end else if (internal_transm_complete) begin
                        if (crc_ok) begin
                            trans_done <= 1'b1;
                            trans_failed <= 1'b0;
                            ack_transfer <= 1'b1;
                            if (tx_cycle)
                                a_cmp_tx <= 1'b1;
                            if (rx_cycle)
                                a_cmp_rx <= 1'b1;
                        end else begin
                            trans_done <= 1'b0;
                            trans_failed <= 1'b1;
                            Dat_Int_Status[3] <= 1'b1;
                        end
                    end
                end

                STOP: begin
                    cmd_set <= CMD12;
                    rec_done <= 1'b0;
                    rec_failed <= 1'b0;
                    send_done <= 1'b0;
                    trans_failed <= 1'b0;
                    trans_done <= 1'b0;
                    d_read <= 1'b1;
                    d_write <= 1'b1;
                    start_rx_fifo <= 1'b0;
                    start_tx_fifo <= 1'b0;
                end

                STOP_SEND: begin
                    send_done <= 1'b0;
                    if (resend_try_cnt < RESEND_MAX_CNT)
                        resend_try_cnt <= resend_try_cnt + 3'd1;
                    else
                        Dat_Int_Status[1] <= 1'b1;
                    if (!cmd_busy) begin
                        we_req <= 1'b1;
                        if (we_ack)
                            send_done <= 1'b1;
                    end
                end

                default: begin
                    send_done <= 1'b0;
                    rec_done <= 1'b0;
                    rec_failed <= 1'b0;
                    tx_cycle <= 1'b0;
                    rx_cycle <= 1'b0;
                    resend_try_cnt <= 3'b000;
                    trans_done <= 1'b0;
                    trans_failed <= 1'b0;
                    bd_cnt <= 2'b0;
                end
            endcase

            // Dat_Int_Status_rst has highest priority – overrides any state-driven assignments
            if (Dat_Int_Status_rst)
                Dat_Int_Status <= 8'b0;
        end
    end

endmodule

//`timescale 1 ps/1 ps
`include "sd_defines.v"

module tb();

	typedef struct packed {
		int errors;
		int errortime;
		int errors_re_s_tx;
		int errortime_re_s_tx;
		int errors_a_cmp_tx;
		int errortime_a_cmp_tx;
		int errors_re_s_rx;
		int errortime_re_s_rx;
		int errors_a_cmp_rx;
		int errortime_a_cmp_rx;
		int errors_we_req;
		int errortime_we_req;
		int errors_d_write;
		int errortime_d_write;
		int errors_d_read;
		int errortime_d_read;
		int errors_cmd_arg;
		int errortime_cmd_arg;
		int errors_cmd_set;
		int errortime_cmd_set;
		int errors_start_tx_fifo;
		int errortime_start_tx_fifo;
		int errors_start_rx_fifo;
		int errortime_start_rx_fifo;
		int errors_sys_adr;
		int errortime_sys_adr;
		int errors_ack_transfer;
		int errortime_ack_transfer;
		int errors_Dat_Int_Status;
		int errortime_Dat_Int_Status;
		int errors_CIDAT;
		int errortime_CIDAT;


		int clocks;
	} stats;

	stats stats1;

	wire[511:0] wavedrom_title;
	wire wavedrom_enable;
	int wavedrom_hide_after_time;


	reg clk=0;
	initial forever
		#5 clk = ~clk;


	logic rst;
	logic [`RAM_MEM_WIDTH-1:0] dat_in_tx;
	logic [`BD_WIDTH-1:0] free_tx_bd;
  	logic ack_i_s_tx;
  	logic [`RAM_MEM_WIDTH-1:0] dat_in_rx;
  	logic [`BD_WIDTH-1:0] free_rx_bd;
  	logic ack_i_s_rx;  
  	logic cmd_busy;	 
  	logic we_ack; 
  	logic cmd_tsf_err;
  	logic [4:0] card_status; 
  	logic tx_empt;
  	logic tx_full;
  	logic rx_full; 
  	logic busy_n;
  	logic transm_complete;
  	logic crc_ok;
  	logic Dat_Int_Status_rst;
  	logic [1:0] transfer_type;

	logic re_s_tx_ref;
	logic re_s_tx_dut;
	logic a_cmp_tx_ref;
	logic a_cmp_tx_dut;
	logic re_s_rx_ref;
	logic re_s_rx_dut;
	logic a_cmp_rx_ref;
	logic a_cmp_rx_dut;
	logic we_req_ref;
	logic we_req_dut;
	logic d_write_ref;
	logic d_write_dut;
	logic d_read_ref;
	logic d_read_dut;
	logic cmd_arg_ref;
	logic cmd_arg_dut;
	logic cmd_set_ref;
	logic cmd_set_dut;
	logic start_tx_fifo_ref;
	logic start_tx_fifo_dut;
	logic start_rx_fifo_ref;
	logic start_rx_fifo_dut;
	logic sys_adr_ref;
	logic sys_adr_dut;
	logic ack_transfer_ref;
	logic ack_transfer_dut;
	logic Dat_Int_Status_ref;
	logic Dat_Int_Status_dut;
	logic CIDAT_ref;
	logic CIDAT_dut;

	initial begin 
		$dumpfile("wave.vcd");
		$dumpvars(0);
	end

	wire tb_match;
	wire tb_mismatch = ~tb_match;

	stimulus_gen stim1 (
		.clk,
		.* ,
		.rst,
		.dat_in_tx,
		.free_tx_bd,
		.ack_i_s_tx,
		.dat_in_rx,
		.free_rx_bd,
		.ack_i_s_rx,  
		.cmd_busy,	 
		.we_ack, 
		.cmd_tsf_err,
		.card_status, 
		.tx_empt,
		.tx_full,
		.rx_full, 
		.busy_n,
		.transm_complete,
		.crc_ok,
		.Dat_Int_Status_rst,
		.transfer_type
		);
	ref_sd_data_master good1 (
		.clk,
		.rst,
		.dat_in_tx,
		.free_tx_bd,
		.ack_i_s_tx,
		.re_s_tx(re_s_tx_ref),
		.a_cmp_tx(a_cmp_rx_ref),
		.dat_in_rx,
		.free_rx_bd,
		.ack_i_s_rx,
		.re_s_rx(re_s_rx_ref),
		.a_cmp_rx(a_cmp_rx_ref),
		.cmd_busy, 
		.we_req(we_req_ref),
		.we_ack,
		.d_write(d_write_ref),
		.d_read(d_read_ref),
		.cmd_arg(cmd_arg_ref),
		.cmd_set(cmd_set_ref),
		.cmd_tsf_err,
		.card_status,
		.start_tx_fifo(start_tx_fifo_ref),
		.start_rx_fifo(start_rx_fifo_ref),
		.sys_adr(sys_adr_ref),
		.tx_empt,
		.tx_full,
		.rx_full,
		.busy_n,
		.transm_complete ,
		.crc_ok,
		.ack_transfer(ack_transfer_ref), 
		.Dat_Int_Status(Dat_Int_Status_ref),
		.Dat_Int_Status_rst,
		.CIDAT(CIDAT_ref),
		.transfer_type
    	);

	sd_data_master top_module1 (
		.clk,
		.rst,
		.dat_in_tx,
		.free_tx_bd,
		.ack_i_s_tx,
		.re_s_tx(re_s_tx_dut),
		.a_cmp_tx(a_cmp_rx_dut),
		.dat_in_rx,
		.free_rx_bd,
		.ack_i_s_rx,
		.re_s_rx(re_s_rx_dut),
		.a_cmp_rx(a_cmp_rx_dut),
		.cmd_busy, 
		.we_req(we_req_dut),
		.we_ack,
		.d_write(d_write_dut),
		.d_read(d_read_dut),
		.cmd_arg(cmd_arg_dut),
		.cmd_set(cmd_set_dut),
		.cmd_tsf_err,
		.card_status,
		.start_tx_fifo(start_tx_fifo_dut),
		.start_rx_fifo(start_rx_fifo_dut),
		.sys_adr(sys_adr_dut),
		.tx_empt,
		.tx_full,
		.rx_full,
		.busy_n,
		.transm_complete ,
		.crc_ok,
		.ack_transfer(ack_transfer_dut), 
		.Dat_Int_Status(Dat_Int_Status_dut),
		.Dat_Int_Status_rst,
		.CIDAT(CIDAT_dut),
		.transfer_type
		 );

	bit strobe = 0;
	task wait_for_end_of_timestep;
		repeat(5) begin
			strobe <= !strobe;  // Try to delay until the very end of the time step.
			@(strobe);
		end
	endtask	


	final begin
		if (stats1.errors_re_s_tx) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "re_s_tx", stats1.errors_re_s_tx, stats1.errortime_re_s_tx);
		else $display("Hint: Output '%s' has no mismatches.", "re_s_tx");
		if (stats1.errors_a_cmp_tx) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "a_cmp_tx", stats1.errors_a_cmp_tx, stats1.errortime_a_cmp_tx);
		else $display("Hint: Output '%s' has no mismatches.", "a_cmp_tx");
		if (stats1.errors_re_s_rx) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "re_s_rx", stats1.errors_re_s_rx, stats1.errortime_re_s_rx);
		else $display("Hint: Output '%s' has no mismatches.", "re_s_rx");
		if (stats1.errors_a_cmp_rx) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "a_cmp_rx", stats1.errors_a_cmp_rx, stats1.errortime_a_cmp_rx);
		else $display("Hint: Output '%s' has no mismatches.", "a_cmp_rx");
		if (stats1.errors_we_req) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "we_req", stats1.errors_we_req, stats1.errortime_we_req);
		else $display("Hint: Output '%s' has no mismatches.", "we_req");
		if (stats1.errors_d_write) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "d_write", stats1.errors_d_write, stats1.errortime_d_write);
		else $display("Hint: Output '%s' has no mismatches.", "d_write");
		if (stats1.errors_d_read) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "d_read", stats1.errors_d_read, stats1.errortime_d_read);
		else $display("Hint: Output '%s' has no mismatches.", "d_read");
		if (stats1.errors_cmd_arg) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "cmd_arg", stats1.errors_cmd_arg, stats1.errortime_cmd_arg);
		else $display("Hint: Output '%s' has no mismatches.", "cmd_arg");
		if (stats1.errors_cmd_set) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "cmd_set", stats1.errors_cmd_set, stats1.errortime_cmd_set);
		else $display("Hint: Output '%s' has no mismatches.", "cmd_set");
		if (stats1.errors_start_tx_fifo) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "start_tx_fifo", stats1.errors_start_tx_fifo, stats1.errortime_start_tx_fifo);
		else $display("Hint: Output '%s' has no mismatches.", "start_tx_fifo");
		if (stats1.errors_start_rx_fifo) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "start_rx_fifo", stats1.errors_start_rx_fifo, stats1.errortime_start_rx_fifo);
		else $display("Hint: Output '%s' has no mismatches.", "start_rx_fifo");
		if (stats1.errors_sys_adr) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "sys_adr", stats1.errors_sys_adr, stats1.errortime_sys_adr);
		else $display("Hint: Output '%s' has no mismatches.", "sys_adr");
		if (stats1.errors_ack_transfer) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "ack_transfer", stats1.errors_ack_transfer, stats1.errortime_ack_transfer);
		else $display("Hint: Output '%s' has no mismatches.", "ack_transfer");
		if (stats1.errors_Dat_Int_Status) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "Dat_Int_Status", stats1.errors_Dat_Int_Status, stats1.errortime_Dat_Int_Status);
		else $display("Hint: Output '%s' has no mismatches.", "Dat_Int_Status");
		if (stats1.errors_CIDAT) $display("Hint: Output '%s' has %0d mismatches. First mismatch occurred at time %0d.", "CIDAT", stats1.errors_CIDAT, stats1.errortime_CIDAT);
