46: 
47:     localparam SIZE           = 9;
48:     localparam IDLE           = 9'b000000001;
49:     localparam GET_TX_BD      = 9'b000000010;
50:     localparam GET_RX_BD      = 9'b000000100;
51:     localparam SEND_CMD       = 9'b000001000;
52:     localparam RECIVE_CMD     = 9'b000010000;
53:     localparam DATA_TRANSFER  = 9'b000100000;
54:     localparam STOP           = 9'b001000000;
55:     localparam STOP_SEND      = 9'b010000000;
56:     localparam RESEND_MAX_CNT = 3;
57:     localparam BD_SIZE        = 8;
58:     localparam BD_EMPTY       = 2;        // BD_SIZE/4 (16-bit memory)
59:     localparam READ_CYCLE     = 4;
60:     // Internal registers
61:     reg          send_done;
62:     reg          rec_done;
63:     reg          rec_failed;
64:     reg          tx_cycle;
65:     reg          rx_cycle;
66:     reg [2:0]    resend_try_cnt;
67:     reg [8:0]    state;
68:     reg [8:0]    next_state;
69:     reg          trans_done;
70:     reg          trans_failed;
71:     reg          internal_transm_complete;
72:     reg          transm_complete_q;
73:     reg [2:0]    bd_cnt;                 // 3 bits for READ_CYCLE=4
74: 
75:     // Combinational next-state logic (explicit sensitivity list)
76:     always @(state or free_tx_bd or free_rx_bd or tx_full or send_done or
77:              rec_done or rec_failed or trans_done or trans_failed or bd_cnt) begin
78:         next_state = state;   // default hold
79:         case (state)
80:             IDLE: begin
81:                 if (free_tx_bd != BD_EMPTY)
82:                     next_state = GET_TX_BD;
83:                 else if (free_rx_bd != BD_EMPTY)
84:                     next_state = GET_RX_BD;
85:                 else
86:                     next_state = IDLE;
87:             end
88:             GET_TX_BD: begin
89:                 if ((bd_cnt > (READ_CYCLE - 1)) && (tx_full == 1'b1))
90:                     next_state = SEND_CMD;
