92:                     next_state = GET_TX_BD;
93:             end
94:             GET_RX_BD: begin
95:                 if (bd_cnt > (READ_CYCLE - 1))
96:                     next_state = SEND_CMD;
97:                 else
98:                     next_state = GET_RX_BD;
99:             end
100:             SEND_CMD: begin
101:                 if (send_done == 1'b1)
102:                     next_state = RECIVE_CMD;
103:                 else
104:                     next_state = SEND_CMD;
105:             end
106:             RECIVE_CMD: begin
107:                 if (rec_done == 1'b1)
108:                     next_state = DATA_TRANSFER;
109:                 else if (rec_failed == 1'b1)
110:                     next_state = SEND_CMD;
111:                 else
112:                     next_state = RECIVE_CMD;
113:             end
114:             DATA_TRANSFER: begin
115:                 if (trans_done == 1'b1)
116:                     next_state = IDLE;
117:                 else if (trans_failed == 1'b1)
118:                     next_state = STOP;
119:                 else
120:                     next_state = DATA_TRANSFER;
121:             end
122:             STOP: begin
123:                 next_state = STOP_SEND;
124:             end
125:             STOP_SEND: begin
126:                 if (send_done == 1'b1)
127:                     next_state = IDLE;
128:                 else
129:                     next_state = STOP_SEND;
130:             end
131:             default: next_state = IDLE;
132:         endcase
133:     end
