135:     // Sequential state register and output register update
136:     always @(posedge clk or posedge rst) begin
137:         if (rst) begin
138:             state <= IDLE;
139:             send_done <= 1'b0;
140:             rec_done <= 1'b0;
141:             rec_failed <= 1'b0;
142:             tx_cycle <= 1'b0;
143:             rx_cycle <= 1'b0;
144:             resend_try_cnt <= 3'b000;
145:             trans_done <= 1'b0;
146:             trans_failed <= 1'b0;
147:             internal_transm_complete <= 1'b0;
148:             transm_complete_q <= 1'b0;
149:             sys_adr <= 32'b0;
150:             cmd_arg <= 32'b0;
151:             cmd_set <= 16'b0;
152:             CIDAT <= 1'b0;
153:             Dat_Int_Status <= 8'b0;
154:             bd_cnt <= 3'b0;
155:             re_s_tx <= 1'b0;
