228: 
229:                 GET_RX_BD: begin
230:                     re_s_rx <= 1'b1;
231:                     tx_cycle <= 1'b0;
232:                     rx_cycle <= 1'b1;
233:                     send_done <= 1'b0;
234:                     rec_done <= 1'b0;
235:                     rec_failed <= 1'b0;
236:                     trans_done <= 1'b0;
237:                     trans_failed <= 1'b0;
