254:                         end else if (bd_cnt == 3'd3) begin
255:                             cmd_arg[31:16] <= dat_in_rx[15:0];
256:                             bd_cnt <= 3'd4;
257:                         end
258:                     end
259:                 end
260: 
261:                 SEND_CMD: begin
262:                     bd_cnt <= 3'b0;
263:                     send_done <= 1'b0;
264:                     rec_done <= 1'b0;
265:                     rec_failed <= 1'b0;
266:                     if (rx_cycle) begin
267:                         d_read <= 1'b1;
268:                         d_write <= 1'b0;
269:                     end else if (tx_cycle) begin
270:                         d_read <= 1'b0;
271:                         d_write <= 1'b1;
272:                     end else begin
273:                         d_read <= 1'b0;
274:                         d_write <= 1'b0;
275:                     end
276:                     if (!cmd_busy) begin
277:                         we_req <= 1'b1;
278:                         if (we_ack)
279:                             send_done <= 1'b1;
280:                     end
281:                 end
282: 
283:                 RECIVE_CMD: begin
284:                     send_done <= 1'b0;
285:                     if (rx_cycle)
286:                         start_rx_fifo <= 1'b1;
287:                     if (!cmd_busy) begin
288:                         if (cmd_tsf_err) begin
289:                             rec_failed <= 1'b1;
290:                             rec_done <= 1'b0;
291:                             Dat_Int_Status[0] <= 1'b1;
292:                         end else if ((card_status[0] == 1'b1) &&
293:                                      ((card_status[4:1] == 4'd4) ||
294:                                       (card_status[4:1] == 4'd5) ||
295:                                       (card_status[4:1] == 4'd6))) begin
296:                             rec_done <= 1'b1;
297:                             rec_failed <= 1'b0;
298:                         end else begin
299:                             rec_done <= 1'b0;
300:                             rec_failed <= 1'b1;
301:                         end
302:                     end
303:                 end
304: 
305:                 DATA_TRANSFER: begin
306:                     rec_done <= 1'b0;
307:                     rec_failed <= 1'b0;
308:                     if (tx_cycle && tx_empt) begin
309:                         trans_failed <= 1'b1;
310:                         Dat_Int_Status[2] <= 1'b1;
311:                     end else if (rx_cycle && rx_full) begin
312:                         trans_failed <= 1'b1;
313:                         Dat_Int_Status[2] <= 1'b1;
314:                     end else if (internal_transm_complete) begin
315:                         if (crc_ok) begin
316:                             trans_done <= 1'b1;
317:                             trans_failed <= 1'b0;
318:                             ack_transfer <= 1'b1;
319:                             if (tx_cycle)
320:                                 a_cmp_tx <= 1'b1;
321:                             if (rx_cycle)
322:                                 a_cmp_rx <= 1'b1;
323:                         end else begin
324:                             trans_done <= 1'b0;
325:                             trans_failed <= 1'b1;
326:                             Dat_Int_Status[3] <= 1'b1;
327:                         end
328:                     end
329:                 end
330: 
331:                 STOP: begin
332:                     cmd_set <= CMD12;
333:                     rec_done <= 1'b0;
334:                     rec_failed <= 1'b0;
335:                     send_done <= 1'b0;
336:                     trans_failed <= 1'b0;
337:                     trans_done <= 1'b0;
338:                     d_read <= 1'b1;
339:                     d_write <= 1'b1;
340:                     start_rx_fifo <= 1'b0;
341:                     start_tx_fifo <= 1'b0;
342:                 end
343: 
344:                 STOP_SEND: begin
345:                     send_done <= 1'b0;
346:                     if (resend_try_cnt < RESEND_MAX_CNT)
347:                         resend_try_cnt <= resend_try_cnt + 3'd1;
348:                     else
349:                         Dat_Int_Status[1] <= 1'b1;
350:                     if (!cmd_busy) begin
351:                         we_req <= 1'b1;
352:                         if (we_ack)
353:                             send_done <= 1'b1;
354:                     end
355:                 end
356: 
357:                 default: begin
358:                     send_done <= 1'b0;
359:                     rec_done <= 1'b0;
360:                     rec_failed <= 1'b0;
361:                     tx_cycle <= 1'b0;
362:                     rx_cycle <= 1'b0;
363:                     resend_try_cnt <= 3'b000;
364:                     trans_done <= 1'b0;
365:                     trans_failed <= 1'b0;
366:                     bd_cnt <= 2'b0;
367:                 end
368:             endcase
369: 
370:             // Dat_Int_Status_rst has highest priority – overrides any state-driven assignments
371:             if (Dat_Int_Status_rst)
372:                 Dat_Int_Status <= 8'b0;
373:         end
374:     end
375: 
