                        bd_cnt <= bd_cnt + 3'd1;
                    end else if (bd_cnt == 3'd2) begin
                        cmd_arg[31:16] <= dat_in_rx;
                        bd_cnt <= bd_cnt + 3'd1;
                    end else if (bd_cnt == 3'd3) begin
                        cmd_arg[15:0] <= dat_in_rx;
                        bd_cnt <= bd_cnt + 3'd1;
                    end else begin
                        bd_cnt <= bd_cnt + 3'd1;
                    end
                end
            end

            SEND_CMD: begin
                if (tx_cycle) begin
                    d_write <= 1'b1;
                    d_read <= 1'b0;
                end else if (rx_cycle) begin
                    d_write <= 1'b0;
                    d_read <= 1'b1;
                end

                if (!cmd_busy) begin
                    we_req <= 1'b1;
                end

                if (we_ack) begin
                    send_done <= 1'b1;
                end
            end

            RECIVE_CMD: begin
                if (rx_cycle) begin
                    start_rx_fifo <= 1'b1;
                end

                if (!cmd_busy) begin
                    if (cmd_tsf_err) begin
                        rec_failed <= 1'b1;
                    end else if ((card_status[0] == 1'b1) &&
                                 ((card_status[4:1] == 4'd4) ||
                                  (card_status[4:1] == 4'd5) ||
                                  (card_status[4:1] == 4'd6))) begin
                        rec_done <= 1'b1;
                    end else begin
                        rec_failed <= 1'b1;
                    end
                end
            end

            DATA_TRANSFER: begin
                if (tx_cycle && tx_empt) begin
                    trans_failed <= 1'b1;
                end else if (rx_cycle && rx_full) begin
                    trans_failed <= 1'b1;
                end else if (internal_transm_complete) begin
                    if (crc_ok) begin
                        trans_done <= 1'b1;
                        ack_transfer <= 1'b1;

                        if (tx_cycle) begin
                            a_cmp_tx <= 1'b1;
                        end

                        if (rx_cycle) begin
                            a_cmp_rx <= 1'b1;
                        end
                    end else begin
                        trans_failed <= 1'b1;
                    end
                end
            end

            STOP: begin
                cmd_set <= CMD12;
                rec_done <= 1'b0;
                rec_failed <= 1'b0;
                send_done <= 1'b0;
                trans_failed <= 1'b0;
                trans_done <= 1'b0;
                d_read <= 1'b1;
                d_write <= 1'b1;
                start_rx_fifo <= 1'b0;
                start_tx_fifo <= 1'b0;
            end

            STOP_SEND: begin
                d_read <= 1'b1;
                d_write <= 1'b1;

                if (!cmd_busy) begin
                    we_req <= 1'b1;
                end

                if (we_ack) begin
                    send_done <= 1'b1;

                    if (resend_try_cnt != RESEND_MAX_CNT[2:0]) begin
                        resend_try_cnt <= resend_try_cnt + 3'd1;
                    end

                    if (!Dat_Int_Status_rst && (resend_try_cnt >= RESEND_MAX_CNT[2:0])) begin
                        Dat_Int_Status[1] <= 1'b1;
                    end
                end
            end

            default: begin
                send_done <= 1'b0;
                rec_done <= 1'b0;
                rec_failed <= 1'b0;
                tx_cycle <= 1'b0;
                rx_cycle <= 1'b0;
                bd_cnt <= 3'b000;
                trans_done <= 1'b0;
                trans_failed <= 1'b0;
            end
        endcase
    end
end

