			transm_complete = ($random%2);
			crc_ok = ($random%2);
			Dat_Int_Status_rst = ($random%2);   
			transfer_type = $random;
			//reset = 1;
			reset = !($random & 31);
		end

		@(posedge clk);
		repeat(30000) @(posedge clk, negedge clk) begin
			dat_in_tx = $random;
			free_tx_bd = $random;
			ack_i_s_tx = ($random%2);
			dat_in_rx = $random;
			free_rx_bd = $random;
			ack_i_s_rx = ($random%2);   
